import base64

# The dashboard HTML safely encoded so the chat app cannot break it!
encoded_html = """"""

# Decode it back to HTML and write it
html_code = base64.b64decode(encoded_html).decode('utf-8')

with open("index.html", "w", encoding="utf-8") as file:
    file.write(html_code)

print("✅ System Hacked: Perfect index.html has been generated!")